begin;

-- Mobile LIVE/event/album sources are intentionally unseeded. Until an operator
-- publishes a versioned row, reads report configured=false and writes are blocked.
create table public.mobile_participation_events (
  id uuid primary key default extensions.gen_random_uuid(),
  slug text not null unique check(slug~'^[a-z0-9]+(-[a-z0-9]+)*$'),
  celebrity_id uuid not null references public.celebrities(id) on delete restrict,
  event_kind text not null check(event_kind in('concert','byus_day','general')),
  policy_version text not null check(length(btrim(policy_version))between 1 and 80),
  state text not null default'draft' check(state in('draft','published','cancelled','ended')),
  starts_at timestamptz not null, ends_at timestamptz not null,
  title_ko text not null check(length(btrim(title_ko))between 1 and 200),
  title_en text not null check(length(btrim(title_en))between 1 and 200),
  summary_ko text not null default'', summary_en text not null default'',
  application_url text, revision integer not null default 1 check(revision>0),
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
  check(starts_at<ends_at),check(application_url is null or application_url~'^https://')
);

create table public.mobile_participation_checkins (
  id uuid primary key default extensions.gen_random_uuid(),
  event_id uuid not null references public.mobile_participation_events(id) on delete restrict,
  app_user_id uuid not null references public.app_users(id) on delete restrict,
  status text not null default'valid' check(status in('valid','rejected','revoked')),
  source text not null check(source in('qr','staff','linked_web')),
  policy_version text not null,confirmed_at timestamptz not null default clock_timestamp(),
  confirmed_by_admin_id uuid references public.admin_allowlist(id) on delete restrict,
  unique(event_id,app_user_id)
);

create table public.mobile_participation_contexts (
  id uuid primary key default extensions.gen_random_uuid(),
  context_type text not null check(context_type in('live','event','album')),
  source_live_event_id uuid references public.live_events(id) on delete restrict,
  source_event_id uuid references public.mobile_participation_events(id) on delete restrict,
  celebrity_id uuid not null references public.celebrities(id) on delete restrict,
  slug text not null unique check(slug~'^[a-z0-9]+(-[a-z0-9]+)*$'),
  policy_version text not null check(length(btrim(policy_version))between 1 and 80),
  state text not null default'draft' check(state in('draft','published','closed')),
  opens_at timestamptz not null,closes_at timestamptz not null,
  require_checkin boolean not null default false,
  album_kind text check(album_kind is null or album_kind in('concert','byus_day')),
  revision integer not null default 1 check(revision>0),
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
  check(opens_at<closes_at),
  check((context_type='live'and source_live_event_id is not null and source_event_id is null and album_kind is null)
    or(context_type='event'and source_event_id is not null and source_live_event_id is null and album_kind is null)
    or(context_type='album'and source_event_id is not null and source_live_event_id is null and album_kind is not null)),
  unique(context_type,source_live_event_id),unique(context_type,source_event_id)
);

create table public.mobile_participation_posts (
  id uuid primary key default extensions.gen_random_uuid(),context_id uuid not null references public.mobile_participation_contexts(id) on delete restrict,
  app_user_id uuid not null references public.app_users(id) on delete restrict,
  kind text not null check(kind in('post','photo','video','question','memory')),
  body text not null default'' check(length(body)<=5000),revision integer not null default 1 check(revision>0),
  status text not null default'valid' check(status in('valid','deleted','rejected')),
  request_key uuid not null,payload_hash text not null check(payload_hash~'^[a-f0-9]{32}$'),
  hidden_by_admin_id uuid references public.admin_allowlist(id) on delete restrict,hidden_reason text,
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
  unique(app_user_id,request_key),check(body<>''or kind in('photo','video'))
);
create index mobile_participation_posts_feed on public.mobile_participation_posts(context_id,updated_at,id)where status='valid';

create table public.mobile_participation_post_media (
  post_id uuid not null references public.mobile_participation_posts(id) on delete restrict,
  asset_id uuid not null unique references public.mobile_media_assets(id) on delete restrict,
  position smallint not null check(position between 0 and 3),primary key(post_id,position)
);
create table public.mobile_participation_comments (
  id uuid primary key default extensions.gen_random_uuid(),post_id uuid not null references public.mobile_participation_posts(id) on delete restrict,
  app_user_id uuid not null references public.app_users(id) on delete restrict,body text not null check(length(btrim(body))between 1 and 1000),
  revision integer not null default 1,status text not null default'valid' check(status in('valid','deleted','rejected')),
  request_key uuid not null,hidden_by_admin_id uuid references public.admin_allowlist(id) on delete restrict,hidden_reason text,
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(app_user_id,request_key)
);
create table public.mobile_participation_reactions (
  target_type text not null check(target_type in('post','comment')),target_id uuid not null,
  app_user_id uuid not null references public.app_users(id) on delete cascade,
  emoji text not null check(emoji in('like','heart','laugh','wow','sad')),updated_at timestamptz not null default clock_timestamp(),
  primary key(target_type,target_id,app_user_id)
);

create table public.mobile_participation_activity_policies (
  id uuid primary key default extensions.gen_random_uuid(),context_id uuid not null references public.mobile_participation_contexts(id) on delete restrict,
  policy_version text not null,activity_kind text not null check(activity_kind in('video','mission')),
  state text not null default'draft' check(state in('draft','published','closed')),
  opens_at timestamptz not null,closes_at timestamptz not null,completion_seconds integer not null check(completion_seconds>0),
  max_heartbeat_gap_seconds integer not null check(max_heartbeat_gap_seconds between 2 and 60),
  reward_config jsonb,revision integer not null default 1 check(revision>0),created_at timestamptz not null default clock_timestamp(),unique(context_id,policy_version),check(opens_at<closes_at)
);
create table public.mobile_participation_activity_sessions (
  id uuid primary key default extensions.gen_random_uuid(),activity_id uuid not null references public.mobile_participation_activity_policies(id) on delete restrict,
  app_user_id uuid not null references public.app_users(id) on delete restrict,request_key uuid not null,payload_hash text not null,
  state text not null default'viewing' check(state in('viewing','completing','completed','rejected','deleted')),
  version integer not null default 1 check(version>0),watched_seconds integer not null default 0 check(watched_seconds>=0),
  last_heartbeat_at timestamptz not null default clock_timestamp(),completed_at timestamptz,rejection_code text,
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
  unique(app_user_id,request_key),unique(activity_id,app_user_id)
);
create table public.mobile_participation_activity_rewards (
  session_id uuid primary key references public.mobile_participation_activity_sessions(id) on delete restrict,
  status text not null check(status in('pending','awarded','cancelled','revoked')),reward_snapshot jsonb not null,
  updated_at timestamptz not null default clock_timestamp()
);

create table public.mobile_participation_votes (
  id uuid primary key default extensions.gen_random_uuid(),context_id uuid not null references public.mobile_participation_contexts(id) on delete restrict,
  policy_version text not null,question text not null check(length(btrim(question))between 1 and 500),
  state text not null default'draft' check(state in('draft','published','closed')),opens_at timestamptz not null,closes_at timestamptz not null,
  max_selections integer not null check(max_selections between 1 and 20),change_allowed boolean not null default false,
  result_visibility text not null check(result_visibility in('after_vote','after_close','hidden')),
  revision integer not null default 1 check(revision>0),created_at timestamptz not null default clock_timestamp(),unique(context_id,policy_version),check(opens_at<closes_at)
);
create table public.mobile_participation_vote_options (
  id uuid primary key default extensions.gen_random_uuid(),vote_id uuid not null references public.mobile_participation_votes(id) on delete restrict,
  label text not null check(length(btrim(label))between 1 and 300),display_order integer not null,unique(vote_id,id),unique(vote_id,display_order)
);
create table public.mobile_participation_vote_responses (
  vote_id uuid not null references public.mobile_participation_votes(id) on delete restrict,app_user_id uuid not null references public.app_users(id) on delete restrict,
  option_ids uuid[] not null,request_key uuid not null,payload_hash text not null,revision integer not null default 1,
  created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(vote_id,app_user_id),unique(app_user_id,request_key)
);

create table public.mobile_participation_qr_codes (
  id uuid primary key default extensions.gen_random_uuid(),token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),
  purpose text not null check(purpose in('profile','stamp','live','event','space','album','event_checkin','benefit_use','prize_pickup')),
  target_type text not null,target_id uuid not null,owner_app_user_id uuid references public.app_users(id) on delete restrict,
  policy_version text not null,expires_at timestamptz not null,one_time boolean not null default true,staff_required boolean not null default false,
  state text not null default'active' check(state in('active','consumed','revoked')),consumed_at timestamptz,consumed_by_app_user_id uuid references public.app_users(id) on delete restrict,
  created_by_admin_id uuid not null references public.admin_allowlist(id) on delete restrict,created_at timestamptz not null default clock_timestamp(),
  check((state='consumed')=(consumed_at is not null))
);
create table public.mobile_participation_qr_requests (
  id uuid primary key default extensions.gen_random_uuid(),app_user_id uuid not null references public.app_users(id) on delete restrict,
  request_key uuid not null,token_hash text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(app_user_id,request_key)
);
create index mobile_participation_qr_rate on public.mobile_participation_qr_requests(app_user_id,created_at desc);

create table public.mobile_participation_admin_audits (
  id uuid primary key default extensions.gen_random_uuid(),actor_app_user_id uuid not null references public.app_users(id) on delete restrict,
  actor_admin_allowlist_id uuid not null references public.admin_allowlist(id) on delete restrict,action text not null,target_type text not null,target_id uuid,
  correlation_id uuid not null,reason text not null,detail jsonb not null default'{}',created_at timestamptz not null default clock_timestamp()
);

do $$declare t text;begin foreach t in array array['mobile_participation_events','mobile_participation_checkins','mobile_participation_contexts','mobile_participation_posts','mobile_participation_post_media','mobile_participation_comments','mobile_participation_reactions','mobile_participation_activity_policies','mobile_participation_activity_sessions','mobile_participation_activity_rewards','mobile_participation_votes','mobile_participation_vote_options','mobile_participation_vote_responses','mobile_participation_qr_codes','mobile_participation_qr_requests','mobile_participation_admin_audits']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);end loop;end$$;

create function public.mobile_participation_context_access(p_app_user_id uuid,p_context_id uuid,p_for_write boolean default false)returns boolean language plpgsql stable security definer set search_path=''as $$declare c public.mobile_participation_contexts%rowtype;e public.mobile_participation_events%rowtype;begin
 select*into c from public.mobile_participation_contexts where id=p_context_id and state='published';if not found then return false;end if;
 if p_for_write and not(clock_timestamp()>=c.opens_at and clock_timestamp()<c.closes_at)then return false;end if;
 if c.context_type='live'then return exists(select 1 from public.fan_passports p where p.app_user_id=p_app_user_id and p.celebrity_id=c.celebrity_id and p.business_status='issued');end if;
 select*into e from public.mobile_participation_events where id=c.source_event_id and state in('published','ended');if not found then return false;end if;
 if c.context_type='event'then return not c.require_checkin or exists(select 1 from public.mobile_participation_checkins x where x.event_id=e.id and x.app_user_id=p_app_user_id and x.status='valid'and x.policy_version=e.policy_version);end if;
 if c.album_kind='byus_day'then return exists(select 1 from public.mobile_participation_checkins x where x.event_id=e.id and x.app_user_id=p_app_user_id and x.status='valid'and x.policy_version=e.policy_version);end if;
 return exists(select 1 from public.mobile_participation_checkins x where x.event_id=e.id and x.app_user_id=p_app_user_id and x.status='valid'and x.policy_version=e.policy_version)and(p_for_write or exists(select 1 from public.mobile_participation_posts p where p.context_id=c.id and p.app_user_id=p_app_user_id and p.status='valid'));
end$$;

create function public.read_owned_mobile_participation_events(p_app_user_id uuid,p_locale public.content_locale,p_after timestamptz,p_after_id uuid,p_limit integer)returns jsonb language plpgsql stable security definer set search_path=''as $$declare r jsonb;begin perform public.fan_web_lock_active_user(p_app_user_id);with rows as(select e.*from public.mobile_participation_events e where e.state in('published','ended')and(p_after is null or(e.starts_at,e.id)>(p_after,p_after_id))order by e.starts_at,e.id limit least(greatest(p_limit,1),50)+1),page as(select*from rows order by starts_at,id limit least(greatest(p_limit,1),50))select jsonb_build_object('serverNow',clock_timestamp(),'configured',exists(select 1 from public.mobile_participation_events where state in('published','ended')),'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'slug',slug,'kind',event_kind,'policyVersion',policy_version,'state',state,'title',case p_locale when'en'then title_en else title_ko end,'summary',case p_locale when'en'then summary_en else summary_ko end,'startsAt',starts_at,'endsAt',ends_at,'applicationUrl',application_url,'checkin',(select jsonb_build_object('id',x.id,'status',x.status,'confirmedAt',x.confirmed_at)from public.mobile_participation_checkins x where x.event_id=page.id and x.app_user_id=p_app_user_id))order by starts_at,id)from page),'[]'::jsonb),'hasMore',(select count(*)>least(greatest(p_limit,1),50)from rows))into r;return r;end$$;

create function public.read_owned_mobile_participation_event(p_app_user_id uuid,p_event_id uuid,p_locale public.content_locale)returns jsonb language plpgsql stable security definer set search_path=''as $$declare e public.mobile_participation_events%rowtype;r jsonb;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into e from public.mobile_participation_events where id=p_event_id and state in('published','ended');if not found then return null;end if;select jsonb_build_object('serverNow',clock_timestamp(),'event',jsonb_build_object('id',e.id,'slug',e.slug,'kind',e.event_kind,'policyVersion',e.policy_version,'state',e.state,'title',case p_locale when'en'then e.title_en else e.title_ko end,'summary',case p_locale when'en'then e.summary_en else e.summary_ko end,'startsAt',e.starts_at,'endsAt',e.ends_at,'applicationUrl',e.application_url),'checkin',(select jsonb_build_object('id',x.id,'status',x.status,'confirmedAt',x.confirmed_at)from public.mobile_participation_checkins x where x.event_id=e.id and x.app_user_id=p_app_user_id),'contexts',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'type',c.context_type,'slug',c.slug,'policyVersion',c.policy_version,'state',c.state,'access',public.mobile_participation_context_access(p_app_user_id,c.id,false),'writeAllowed',public.mobile_participation_context_access(p_app_user_id,c.id,true),'votePolicyId',(select v.id from public.mobile_participation_votes v where v.context_id=c.id and v.state='published' and clock_timestamp()>=v.opens_at and clock_timestamp()<v.closes_at order by v.opens_at desc,v.id limit 1),'activityPolicyId',(select a.id from public.mobile_participation_activity_policies a where a.context_id=c.id and a.state='published' and clock_timestamp()>=a.opens_at and clock_timestamp()<a.closes_at order by a.opens_at desc,a.id limit 1))order by c.context_type,c.id)from public.mobile_participation_contexts c where c.source_event_id=e.id and c.state<>'draft'),'[]'::jsonb))into r;return r;end$$;

create function public.read_owned_mobile_participation_context(p_app_user_id uuid,p_context_type text,p_context_id uuid,p_after timestamptz,p_after_id uuid,p_limit integer)returns jsonb language plpgsql stable security definer set search_path=''as $$declare c public.mobile_participation_contexts%rowtype;r jsonb;allowed boolean;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into c from public.mobile_participation_contexts where id=p_context_id and context_type=p_context_type and state='published';if not found then return null;end if;allowed:=public.mobile_participation_context_access(p_app_user_id,c.id,false);if not allowed then return jsonb_build_object('serverNow',clock_timestamp(),'pollAfterMs',2000,'access',jsonb_build_object('allowed',false,'reason',case when c.context_type='album'and c.album_kind='concert'then'POST_REQUIRED'else'CHECKIN_REQUIRED'end),'items','[]'::jsonb,'hasMore',false);end if;
 with rows as(select p.*from public.mobile_participation_posts p where p.context_id=c.id and p.status='valid'and not public.fan_web_blocked(p_app_user_id,p.app_user_id)and(p_after is null or(p.updated_at,p.id)>(p_after,p_after_id))order by p.updated_at,p.id limit least(greatest(p_limit,1),50)+1),page as(select*from rows order by updated_at,id limit least(greatest(p_limit,1),50))select jsonb_build_object('serverNow',clock_timestamp(),'pollAfterMs',2000,'access',jsonb_build_object('allowed',true,'reason',null,'writeAllowed',public.mobile_participation_context_access(p_app_user_id,c.id,true)),'context',jsonb_build_object('id',c.id,'type',c.context_type,'policyVersion',c.policy_version,'opensAt',c.opens_at,'closesAt',c.closes_at),'items',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'kind',p.kind,'body',p.body,'revision',p.revision,'author',(select jsonb_build_object('nickname',coalesce(nullif(btrim(profile.nickname),''),'Fan'),'avatarUrl',public.public_fan_avatar_url(u.id))from public.app_users u left join public.user_profiles profile on profile.app_user_id=u.id where u.id=p.app_user_id and u.status='active'),'isMine',p.app_user_id=p_app_user_id,'createdAt',p.created_at,'updatedAt',p.updated_at,'assetIds',coalesce((select jsonb_agg(m.asset_id order by m.position)from public.mobile_participation_post_media m where m.post_id=p.id),'[]'::jsonb),'reactions',coalesce((select jsonb_object_agg(x.emoji,x.n)from(select emoji,count(*)n from public.mobile_participation_reactions where target_type='post'and target_id=p.id group by emoji)x),'{}'::jsonb),'myReaction',(select emoji from public.mobile_participation_reactions where target_type='post'and target_id=p.id and app_user_id=p_app_user_id),'comments',coalesce((select jsonb_agg(jsonb_build_object('id',z.id,'body',z.body,'revision',z.revision,'author',(select jsonb_build_object('nickname',coalesce(nullif(btrim(profile.nickname),''),'Fan'),'avatarUrl',public.public_fan_avatar_url(u.id))from public.app_users u left join public.user_profiles profile on profile.app_user_id=u.id where u.id=z.app_user_id and u.status='active'),'isMine',z.app_user_id=p_app_user_id,'createdAt',z.created_at,'updatedAt',z.updated_at,'reactions',coalesce((select jsonb_object_agg(y.emoji,y.n)from(select emoji,count(*)n from public.mobile_participation_reactions where target_type='comment'and target_id=z.id group by emoji)y),'{}'::jsonb),'myReaction',(select emoji from public.mobile_participation_reactions where target_type='comment'and target_id=z.id and app_user_id=p_app_user_id))order by z.created_at,z.id)from public.mobile_participation_comments z where z.post_id=p.id and z.status='valid'and not public.fan_web_blocked(p_app_user_id,z.app_user_id)),'[]'::jsonb))order by p.updated_at,p.id)from page p),'[]'::jsonb),'hasMore',(select count(*)>least(greatest(p_limit,1),50)from rows))into r;return r;end$$;

create function public.save_owned_mobile_participation_post(p_app_user_id uuid,p_context_type text,p_context_id uuid,p_post_id uuid,p_kind text,p_body text,p_asset_ids uuid[],p_expected_revision integer,p_request_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare p public.mobile_participation_posts%rowtype;ids uuid[]:=coalesce(p_asset_ids,'{}');h text:=md5(jsonb_build_array(p_context_type,p_context_id,p_kind,btrim(coalesce(p_body,'')),ids)::text);valid_count integer;new_id uuid:=coalesce(p_post_id,extensions.gen_random_uuid());begin perform public.fan_web_lock_active_user(p_app_user_id);if p_kind not in('post','photo','video','question','memory')or length(btrim(coalesce(p_body,'')))>5000 or cardinality(ids)>4 or cardinality(ids)<>(select count(distinct x)from unnest(ids)x)or(btrim(coalesce(p_body,''))=''and cardinality(ids)=0)or not public.mobile_participation_context_access(p_app_user_id,p_context_id,true)or not exists(select 1 from public.mobile_participation_contexts where id=p_context_id and context_type=p_context_type)then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;
 perform 1 from public.mobile_media_assets where id=any(ids)order by id for update;select count(*)into valid_count from public.mobile_media_assets where id=any(ids)and app_user_id=p_app_user_id and purpose='participation'and state='ready'and storage_deleted_at is null and(attached_id is null or(attached_type='participation_post'and attached_id=new_id));if valid_count<>cardinality(ids)or(p_kind='photo'and exists(select 1 from public.mobile_media_assets where id=any(ids)and kind<>'image'))or(p_kind='video'and exists(select 1 from public.mobile_media_assets where id=any(ids)and kind<>'video'))then raise exception'MEDIA_INVALID_ASSET';end if;
 if p_post_id is null then select*into p from public.mobile_participation_posts where app_user_id=p_app_user_id and request_key=p_request_key;if found then if p.payload_hash<>h then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;return jsonb_build_object('id',p.id,'revision',p.revision,'replayed',true);end if;insert into public.mobile_participation_posts(id,context_id,app_user_id,kind,body,request_key,payload_hash)values(new_id,p_context_id,p_app_user_id,p_kind,btrim(coalesce(p_body,'')),p_request_key,h)returning*into p;else select*into p from public.mobile_participation_posts where id=p_post_id and app_user_id=p_app_user_id and context_id=p_context_id and status='valid'for update;if not found then raise exception'MOBILE_PARTICIPATION_NOT_FOUND';end if;if p.revision<>p_expected_revision then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where attached_type='participation_post'and attached_id=p.id and not(id=any(ids))and storage_deleted_at is null;update public.mobile_participation_posts set kind=p_kind,body=btrim(coalesce(p_body,'')),revision=revision+1,updated_at=clock_timestamp()where id=p.id returning*into p;delete from public.mobile_participation_post_media where post_id=p.id;end if;
 insert into public.mobile_participation_post_media(post_id,asset_id,position)select p.id,x.id,(x.ord-1)::smallint from unnest(ids)with ordinality x(id,ord);update public.mobile_media_assets a set attached_type='participation_post',attached_id=p.id,attached_version=p.revision,position=(x.ord-1)::smallint,access_scope='participation',updated_at=clock_timestamp()from unnest(ids)with ordinality x(id,ord)where a.id=x.id;return jsonb_build_object('id',p.id,'revision',p.revision,'replayed',false);end$$;

create function public.remove_owned_mobile_participation_post(p_app_user_id uuid,p_post_id uuid,p_expected_revision integer)returns jsonb language plpgsql security definer set search_path=''as $$declare p public.mobile_participation_posts%rowtype;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into p from public.mobile_participation_posts where id=p_post_id and app_user_id=p_app_user_id and status='valid'for update;if not found then raise exception'MOBILE_PARTICIPATION_NOT_FOUND';end if;if p.revision<>p_expected_revision then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;update public.mobile_participation_posts set status='deleted',revision=revision+1,updated_at=clock_timestamp()where id=p.id returning*into p;update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where attached_type='participation_post'and attached_id=p.id and storage_deleted_at is null;return jsonb_build_object('id',p.id,'revision',p.revision,'removed',true);end$$;

create function public.post_owned_mobile_participation_comment(p_app_user_id uuid,p_post_id uuid,p_body text,p_request_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare p public.mobile_participation_posts%rowtype;c public.mobile_participation_comments%rowtype;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into p from public.mobile_participation_posts where id=p_post_id and status='valid';if not found or not public.mobile_participation_context_access(p_app_user_id,p.context_id,true)or length(btrim(coalesce(p_body,'')))not between 1 and 1000 then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;select*into c from public.mobile_participation_comments where app_user_id=p_app_user_id and request_key=p_request_key;if found then if c.post_id<>p_post_id or c.body<>btrim(p_body)then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;return jsonb_build_object('id',c.id,'revision',c.revision,'replayed',true);end if;insert into public.mobile_participation_comments(post_id,app_user_id,body,request_key)values(p_post_id,p_app_user_id,btrim(p_body),p_request_key)returning*into c;update public.mobile_participation_posts set updated_at=clock_timestamp()where id=p_post_id;return jsonb_build_object('id',c.id,'revision',c.revision,'replayed',false);end$$;

create function public.set_owned_mobile_participation_reaction(p_app_user_id uuid,p_target_type text,p_target_id uuid,p_emoji text)returns jsonb language plpgsql security definer set search_path=''as $$declare context_id uuid;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_target_type='post'then select p.context_id into context_id from public.mobile_participation_posts p where p.id=p_target_id and p.status='valid';elsif p_target_type='comment'then select p.context_id into context_id from public.mobile_participation_comments c join public.mobile_participation_posts p on p.id=c.post_id where c.id=p_target_id and c.status='valid'and p.status='valid';else raise exception'MOBILE_PARTICIPATION_INVALID';end if;if context_id is null or not public.mobile_participation_context_access(p_app_user_id,context_id,false)then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;if p_emoji is null then delete from public.mobile_participation_reactions where target_type=p_target_type and target_id=p_target_id and app_user_id=p_app_user_id;elsif p_emoji in('like','heart','laugh','wow','sad')then insert into public.mobile_participation_reactions(target_type,target_id,app_user_id,emoji)values(p_target_type,p_target_id,p_app_user_id,p_emoji)on conflict(target_type,target_id,app_user_id)do update set emoji=excluded.emoji,updated_at=clock_timestamp();else raise exception'MOBILE_PARTICIPATION_INVALID';end if;update public.mobile_participation_posts set updated_at=clock_timestamp()where id=case when p_target_type='post'then p_target_id else(select post_id from public.mobile_participation_comments where id=p_target_id)end;return jsonb_build_object('emoji',p_emoji);end$$;

-- Reuse the common translation/report pipeline by extending only its target resolver.
alter table public.content_reports drop constraint content_reports_target_type_check;
alter table public.content_reports add constraint content_reports_target_type_check check(target_type in('fan_post','fan_post_comment','fan_clip','fan_clip_comment','notice','notice_comment','cheer','live_submission','participation_post','participation_comment'));
alter table public.content_translations drop constraint content_translations_target_type_check;
alter table public.content_translations add constraint content_translations_target_type_check check(target_type in('fan_post','fan_post_comment','fan_clip','fan_clip_comment','notice','notice_comment','cheer','live_submission','participation_post','participation_comment'));
alter function public.fan_web_content_target(uuid,text,uuid,public.content_locale)rename to fan_web_content_target_before_mobile_participation;
create function public.fan_web_content_target(p_app_user_id uuid,p_target_type text,p_target_id uuid,p_locale public.content_locale default'ko')returns jsonb language plpgsql stable security definer set search_path=''as $$declare body text;rev integer;owner_id uuid;celebrity_id uuid;context_id uuid;begin if p_target_type not in('participation_post','participation_comment')then return public.fan_web_content_target_before_mobile_participation(p_app_user_id,p_target_type,p_target_id,p_locale);end if;if p_target_type='participation_post'then select p.body,p.revision,p.app_user_id,p.context_id,c.celebrity_id into body,rev,owner_id,context_id,celebrity_id from public.mobile_participation_posts p join public.mobile_participation_contexts c on c.id=p.context_id where p.id=p_target_id and p.status='valid';else select z.body,z.revision,z.app_user_id,p.context_id,c.celebrity_id into body,rev,owner_id,context_id,celebrity_id from public.mobile_participation_comments z join public.mobile_participation_posts p on p.id=z.post_id join public.mobile_participation_contexts c on c.id=p.context_id where z.id=p_target_id and z.status='valid'and p.status='valid';end if;if not found or not public.mobile_participation_context_access(p_app_user_id,context_id,false)or public.fan_web_blocked(p_app_user_id,owner_id)then return null;end if;return jsonb_build_object('appUserId',owner_id,'celebrityId',celebrity_id,'body',body,'revision',rev,'sourceHash',encode(extensions.digest(body,'sha256'),'hex'),'sourceLocale','und','link','/participation/'||context_id::text);end$$;

alter function public.resolve_admin_content_report(uuid,uuid,uuid,uuid,text,boolean,text)rename to resolve_admin_content_report_before_mobile_participation;
create function public.resolve_admin_content_report(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_correlation_id uuid,p_report_id uuid,p_resolution text,p_hide_target boolean,p_reason text)returns jsonb language plpgsql security definer set search_path=''as $$declare r public.content_reports%rowtype;begin select*into r from public.content_reports where id=p_report_id;if not found or r.target_type not in('participation_post','participation_comment')then return public.resolve_admin_content_report_before_mobile_participation(p_actor_app_user_id,p_actor_admin_allowlist_id,p_correlation_id,p_report_id,p_resolution,p_hide_target,p_reason);end if;perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if p_resolution not in('resolved','dismissed')or(p_resolution='dismissed'and p_hide_target)or length(btrim(coalesce(p_reason,'')))not between 10 and 500 then raise exception'FAN_WEB_INVALID_INPUT';end if;select*into r from public.content_reports where id=p_report_id for update;if r.status<>'open'then if r.status<>p_resolution or r.target_hidden<>p_hide_target then raise exception'FAN_WEB_CONFLICT';end if;return jsonb_build_object('id',r.id,'status',r.status,'targetHidden',r.target_hidden);end if;if p_hide_target and r.target_type='participation_post'then update public.mobile_participation_posts set status='rejected',revision=revision+1,hidden_by_admin_id=p_actor_admin_allowlist_id,hidden_reason=btrim(p_reason),updated_at=clock_timestamp()where id=r.target_id and status='valid';update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=clock_timestamp(),updated_at=clock_timestamp()where attached_type='participation_post'and attached_id=r.target_id and storage_deleted_at is null;elsif p_hide_target then update public.mobile_participation_comments set status='rejected',revision=revision+1,hidden_by_admin_id=p_actor_admin_allowlist_id,hidden_reason=btrim(p_reason),updated_at=clock_timestamp()where id=r.target_id and status='valid';end if;update public.content_reports set status=p_resolution,resolved_at=clock_timestamp(),resolved_by_admin_id=p_actor_admin_allowlist_id,resolution_reason=btrim(p_reason),target_hidden=p_hide_target where id=p_report_id;insert into public.audit_logs(actor_app_user_id,actor_admin_allowlist_id,action,entity_type,entity_id,correlation_id,before_after_summary)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'content.report.resolve','content_report',p_report_id::text,p_correlation_id,jsonb_build_object('status',p_resolution,'targetType',r.target_type,'targetId',r.target_id,'hidden',p_hide_target));return jsonb_build_object('id',p_report_id,'status',p_resolution,'targetHidden',p_hide_target);end$$;

-- Participation media uses the existing upload/validation/cleanup and read grant.
alter table public.mobile_media_assets drop constraint mobile_media_assets_purpose_check;
alter table public.mobile_media_assets add constraint mobile_media_assets_purpose_check check(purpose in('fan_post','fan_clip','dm','certification','participation','support'));
alter table public.mobile_media_assets drop constraint mobile_media_assets_attached_type_check;
alter table public.mobile_media_assets add constraint mobile_media_assets_attached_type_check check(attached_type in('fan_post','fan_clip','dm_message','certification','participation_post','cs_message'));
alter table public.mobile_media_assets drop constraint mobile_media_assets_access_scope_check;
alter table public.mobile_media_assets add constraint mobile_media_assets_access_scope_check check(access_scope in('owner','fan_post','fan_clip','dm','certification','participation','support'));
create or replace function public.reserve_owned_mobile_media(p_app_user_id uuid,p_kind text,p_purpose text,p_content_type text,p_byte_size integer,p_request_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.mobile_media_assets%rowtype;v_id uuid:=extensions.gen_random_uuid();v_hash text;v_ext text;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_request_id is null or p_kind not in('image','video')or p_purpose not in('fan_post','fan_clip','dm','certification','participation','support')or p_content_type not in('image/jpeg','image/png','image/webp','video/mp4','video/quicktime')or p_byte_size not between 1 and 52428800 or(p_kind='image'and(p_content_type not like'image/%'or p_byte_size>8388608))or(p_kind='video'and p_content_type not like'video/%')or(p_purpose in('fan_post','certification','support')and p_kind<>'image')then raise exception'MEDIA_INVALID_INPUT';end if;v_hash:=md5(p_kind||':'||p_purpose||':'||p_content_type||':'||p_byte_size::text);select*into a from public.mobile_media_assets where app_user_id=p_app_user_id and request_id=p_request_id;if found then if a.request_hash<>v_hash or a.state<>'uploading'or a.upload_expires_at<=clock_timestamp()then raise exception'MEDIA_CONFLICT';end if;return jsonb_build_object('assetId',a.id,'storagePath',a.storage_path,'expiresAt',a.upload_expires_at,'replayed',true);end if;if(select count(*)from public.mobile_media_assets where app_user_id=p_app_user_id and created_at>clock_timestamp()-interval'1 minute')>=20 then raise exception'MEDIA_RATE_LIMITED';end if;v_ext:=case p_content_type when'image/jpeg'then'jpg'when'image/png'then'png'when'image/webp'then'webp'when'video/quicktime'then'mov'else'mp4'end;insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,storage_path,thumbnail_path,request_id,request_hash)values(v_id,p_app_user_id,p_kind,p_purpose,p_content_type,p_byte_size,p_app_user_id::text||'/'||v_id::text||'/original.'||v_ext,p_app_user_id::text||'/'||v_id::text||'/thumbnail.webp',p_request_id,v_hash)returning*into a;return jsonb_build_object('assetId',a.id,'storagePath',a.storage_path,'expiresAt',a.upload_expires_at,'replayed',false);end$$;
create or replace function public.authorize_mobile_media_read(p_app_user_id uuid,p_asset_id uuid,p_variant text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare a public.mobile_media_assets%rowtype;allowed boolean:=false;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_variant not in('original','thumbnail')then raise exception'MEDIA_INVALID_INPUT';end if;select*into a from public.mobile_media_assets where id=p_asset_id and state='ready'and storage_deleted_at is null;if not found then return null;end if;allowed:=(a.app_user_id=p_app_user_id and a.access_scope in('owner','certification'))or(a.access_scope='fan_post'and a.attached_type='fan_post'and public.fan_web_content_visible(p_app_user_id,'fan_post',a.attached_id))or(a.access_scope='fan_clip'and a.attached_type='fan_clip'and public.fan_web_content_visible(p_app_user_id,'fan_clip',a.attached_id))or(a.access_scope='participation'and a.attached_type='participation_post'and exists(select 1 from public.mobile_participation_posts p where p.id=a.attached_id and p.status='valid'and public.mobile_participation_context_access(p_app_user_id,p.context_id,false)))or(a.access_scope='dm'and a.attached_type='dm_message'and exists(select 1 from public.social_dm_messages m join public.social_dm_conversations c on c.id=m.conversation_id where m.id=a.attached_id and p_app_user_id in(c.user_low_id,c.user_high_id)and not public.fan_web_blocked(c.user_low_id,c.user_high_id)and not exists(select 1 from public.social_dm_message_deletions d where d.message_id=m.id and d.app_user_id=p_app_user_id)));if not allowed then return null;end if;return jsonb_build_object('storagePath',case when p_variant='thumbnail'then a.thumbnail_path else a.storage_path end,'contentType',case when p_variant='thumbnail'then'image/webp'else a.content_type end);end$$;

create function public.start_owned_mobile_participation_activity(p_app_user_id uuid,p_activity_id uuid,p_request_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.mobile_participation_activity_policies%rowtype;s public.mobile_participation_activity_sessions%rowtype;h text:=md5(p_activity_id::text);begin perform public.fan_web_lock_active_user(p_app_user_id);select*into a from public.mobile_participation_activity_policies where id=p_activity_id and state='published'and clock_timestamp()>=opens_at and clock_timestamp()<closes_at;if not found then raise exception'MOBILE_PARTICIPATION_ACTIVITY_NOT_CONFIGURED';end if;if not public.mobile_participation_context_access(p_app_user_id,a.context_id,false)then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;select*into s from public.mobile_participation_activity_sessions where app_user_id=p_app_user_id and request_key=p_request_key or(activity_id=p_activity_id and app_user_id=p_app_user_id)order by(request_key=p_request_key)desc limit 1 for update;if found then if s.activity_id<>p_activity_id or s.payload_hash<>h then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;return jsonb_build_object('id',s.id,'state',s.state,'version',s.version,'watchedSeconds',s.watched_seconds,'replayed',true);end if;insert into public.mobile_participation_activity_sessions(activity_id,app_user_id,request_key,payload_hash)values(p_activity_id,p_app_user_id,p_request_key,h)returning*into s;return jsonb_build_object('id',s.id,'state',s.state,'version',s.version,'watchedSeconds',s.watched_seconds,'replayed',false);end$$;
create function public.heartbeat_owned_mobile_participation_activity(p_app_user_id uuid,p_session_id uuid,p_expected_version integer,p_foreground boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare s public.mobile_participation_activity_sessions%rowtype;a public.mobile_participation_activity_policies%rowtype;delta integer;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into s from public.mobile_participation_activity_sessions where id=p_session_id and app_user_id=p_app_user_id for update;if not found then raise exception'MOBILE_PARTICIPATION_NOT_FOUND';end if;if s.version<>p_expected_version then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;if s.state<>'viewing'then return jsonb_build_object('id',s.id,'state',s.state,'version',s.version,'watchedSeconds',s.watched_seconds);end if;select*into a from public.mobile_participation_activity_policies where id=s.activity_id;if a.state<>'published'or clock_timestamp()>=a.closes_at then update public.mobile_participation_activity_sessions set state='rejected',rejection_code='ACTIVITY_CLOSED',version=version+1,updated_at=clock_timestamp()where id=s.id returning*into s;else delta:=case when p_foreground then least(a.max_heartbeat_gap_seconds,greatest(0,floor(extract(epoch from(clock_timestamp()-s.last_heartbeat_at)))::integer))else 0 end;update public.mobile_participation_activity_sessions set watched_seconds=watched_seconds+delta,last_heartbeat_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp()where id=s.id returning*into s;end if;return jsonb_build_object('id',s.id,'state',s.state,'version',s.version,'watchedSeconds',s.watched_seconds,'completionSeconds',a.completion_seconds);end$$;
create function public.claim_mobile_participation_activity_completion(p_limit integer default 25)returns jsonb language plpgsql security definer set search_path=''as $$declare r jsonb;begin with candidates as(select s.id from public.mobile_participation_activity_sessions s join public.mobile_participation_activity_policies a on a.id=s.activity_id join public.app_users u on u.id=s.app_user_id and u.status='active'where s.state='viewing'and s.watched_seconds>=a.completion_seconds and a.state='published'and clock_timestamp()<a.closes_at order by s.updated_at for update of s skip locked limit least(greatest(p_limit,1),50)),claimed as(update public.mobile_participation_activity_sessions s set state='completing',version=version+1,updated_at=clock_timestamp()from candidates c where s.id=c.id and s.state='viewing'returning s.*)select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('sessionId',id,'activityId',activity_id,'appUserId',app_user_id,'version',version)),'[]'::jsonb))into r from claimed;return r;end$$;
create function public.finish_mobile_participation_activity_completion(p_session_id uuid,p_expected_version integer,p_accepted boolean,p_rejection_code text default null)returns jsonb language plpgsql security definer set search_path=''as $$declare s public.mobile_participation_activity_sessions%rowtype;a public.mobile_participation_activity_policies%rowtype;begin select*into s from public.mobile_participation_activity_sessions where id=p_session_id for update;if not found or s.state<>'completing'or s.version<>p_expected_version then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;select*into a from public.mobile_participation_activity_policies where id=s.activity_id;if not p_accepted or a.state<>'published'or not exists(select 1 from public.app_users where id=s.app_user_id and status='active')then update public.mobile_participation_activity_sessions set state='rejected',rejection_code=coalesce(p_rejection_code,'ACTIVITY_REJECTED'),version=version+1,updated_at=clock_timestamp()where id=s.id returning*into s;update public.mobile_participation_activity_rewards set status='cancelled',updated_at=clock_timestamp()where session_id=s.id and status='pending';else update public.mobile_participation_activity_sessions set state='completed',completed_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp()where id=s.id returning*into s;insert into public.mobile_participation_activity_rewards(session_id,status,reward_snapshot)values(s.id,case when a.reward_config is null then'awarded'else'pending'end,coalesce(a.reward_config,jsonb_build_object('kind','none')))on conflict(session_id)do nothing;end if;return jsonb_build_object('id',s.id,'state',s.state,'version',s.version,'completedAt',s.completed_at,'rewardStatus',(select status from public.mobile_participation_activity_rewards where session_id=s.id));end$$;

create function public.read_owned_mobile_participation_vote(p_app_user_id uuid,p_vote_id uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare v public.mobile_participation_votes%rowtype;mine uuid[];show_results boolean;r jsonb;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into v from public.mobile_participation_votes where id=p_vote_id and state in('published','closed');if not found then return null;end if;if not public.mobile_participation_context_access(p_app_user_id,v.context_id,false)then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;select option_ids into mine from public.mobile_participation_vote_responses where vote_id=v.id and app_user_id=p_app_user_id;show_results:=v.result_visibility='after_vote'and mine is not null or v.result_visibility='after_close'and clock_timestamp()>=v.closes_at;select jsonb_build_object('serverNow',clock_timestamp(),'vote',jsonb_build_object('id',v.id,'policyVersion',v.policy_version,'question',v.question,'state',case when clock_timestamp()<v.opens_at then'upcoming'when clock_timestamp()<v.closes_at and v.state='published'then'open'else'closed'end,'opensAt',v.opens_at,'closesAt',v.closes_at,'maxSelections',v.max_selections,'changeAllowed',v.change_allowed,'resultVisibility',v.result_visibility,'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'displayOrder',o.display_order,'votes',case when show_results then(select count(*)from public.mobile_participation_vote_responses x where x.vote_id=v.id and o.id=any(x.option_ids))else null end)order by o.display_order)from public.mobile_participation_vote_options o where o.vote_id=v.id),'[]'::jsonb),'mySelection',coalesce(to_jsonb(mine),'[]'::jsonb),'resultsVisible',show_results))into r;return r;end$$;
create function public.submit_owned_mobile_participation_vote(p_app_user_id uuid,p_vote_id uuid,p_option_ids uuid[],p_request_key uuid,p_expected_policy_version text)returns jsonb language plpgsql security definer set search_path=''as $$declare v public.mobile_participation_votes%rowtype;r public.mobile_participation_vote_responses%rowtype;ids uuid[];h text;begin perform public.fan_web_lock_active_user(p_app_user_id);select array_agg(x order by x)into ids from(select distinct unnest(coalesce(p_option_ids,'{}'))x)s;select*into v from public.mobile_participation_votes where id=p_vote_id for update;if not found or v.state<>'published'then raise exception'MOBILE_PARTICIPATION_VOTE_NOT_CONFIGURED';end if;if v.policy_version<>p_expected_policy_version then raise exception'MOBILE_PARTICIPATION_POLICY_CHANGED';end if;if clock_timestamp()<v.opens_at then raise exception'MOBILE_PARTICIPATION_VOTE_NOT_OPEN';elsif clock_timestamp()>=v.closes_at then raise exception'MOBILE_PARTICIPATION_VOTE_CLOSED';end if;if cardinality(ids)not between 1 and v.max_selections or cardinality(ids)<>(select count(*)from public.mobile_participation_vote_options where vote_id=v.id and id=any(ids))then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if not public.mobile_participation_context_access(p_app_user_id,v.context_id,false)then raise exception'MOBILE_PARTICIPATION_FORBIDDEN';end if;h:=md5(jsonb_build_array(v.id,ids,v.policy_version)::text);select*into r from public.mobile_participation_vote_responses where app_user_id=p_app_user_id and request_key=p_request_key;if found then if r.vote_id<>v.id or r.payload_hash<>h then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;return jsonb_build_object('voteId',v.id,'optionIds',r.option_ids,'revision',r.revision,'replayed',true,'serverNow',clock_timestamp());end if;select*into r from public.mobile_participation_vote_responses where vote_id=v.id and app_user_id=p_app_user_id for update;if found and not v.change_allowed then raise exception'MOBILE_PARTICIPATION_VOTE_DUPLICATE';end if;if found then update public.mobile_participation_vote_responses set option_ids=ids,request_key=p_request_key,payload_hash=h,revision=revision+1,updated_at=clock_timestamp()where vote_id=v.id and app_user_id=p_app_user_id returning*into r;else insert into public.mobile_participation_vote_responses(vote_id,app_user_id,option_ids,request_key,payload_hash)values(v.id,p_app_user_id,ids,p_request_key,h)returning*into r;end if;return jsonb_build_object('voteId',v.id,'optionIds',r.option_ids,'revision',r.revision,'replayed',false,'serverNow',clock_timestamp());end$$;

create function public.resolve_owned_mobile_participation_qr(p_app_user_id uuid,p_raw_code text,p_request_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare h text:=encode(extensions.digest(coalesce(p_raw_code,''),'sha256'),'hex');q public.mobile_participation_qr_codes%rowtype;req public.mobile_participation_qr_requests%rowtype;result jsonb;status text;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_request_key is null or length(coalesce(p_raw_code,''))not between 8 and 512 then raise exception'MOBILE_PARTICIPATION_INVALID';end if;select*into req from public.mobile_participation_qr_requests where app_user_id=p_app_user_id and request_key=p_request_key;if found then if req.token_hash<>h then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;return req.result||jsonb_build_object('replayed',true);end if;if(select count(*)from public.mobile_participation_qr_requests where app_user_id=p_app_user_id and created_at>clock_timestamp()-interval'1 minute')>=20 then raise exception'MOBILE_PARTICIPATION_QR_RATE_LIMITED';end if;select*into q from public.mobile_participation_qr_codes where token_hash=h for update;if not found then status:='unknown';elsif q.state='consumed'then status:='used';elsif q.state='revoked'then status:='unknown';elsif q.expires_at<=clock_timestamp()then status:='expired';elsif q.owner_app_user_id is not null and q.owner_app_user_id<>p_app_user_id then status:='unknown';else status:='resolved';if q.one_time and not q.staff_required then update public.mobile_participation_qr_codes set state='consumed',consumed_at=clock_timestamp(),consumed_by_app_user_id=p_app_user_id where id=q.id returning*into q;end if;end if;result:=jsonb_build_object('requestId',extensions.gen_random_uuid(),'status',status,'purpose',case when status in('resolved','used')then q.purpose else null end,'targetType',case when status in('resolved','used')then q.target_type else null end,'targetId',case when status in('resolved','used')then q.target_id else null end,'expiresAt',case when status in('resolved','used','expired')then q.expires_at else null end,'consumedAt',q.consumed_at,'staffConfirmationRequired',coalesce(q.staff_required,false),'replayed',false);insert into public.mobile_participation_qr_requests(id,app_user_id,request_key,token_hash,result)values((result->>'requestId')::uuid,p_app_user_id,p_request_key,h,result);return result;end$$;

create function public.confirm_admin_mobile_participation_qr(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_request_id uuid,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare req public.mobile_participation_qr_requests%rowtype;q public.mobile_participation_qr_codes%rowtype;award public.mobile_benefit_awards%rowtype;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if length(btrim(coalesce(p_reason,'')))not between 10 and 500 then raise exception'MOBILE_PARTICIPATION_INVALID';end if;select*into req from public.mobile_participation_qr_requests where id=p_request_id for update;if not found or req.result->>'status'<>'resolved'then raise exception'MOBILE_PARTICIPATION_QR_NOT_FOUND';end if;select*into q from public.mobile_participation_qr_codes where token_hash=req.token_hash for update;if q.state='consumed'and q.consumed_by_app_user_id=req.app_user_id then return jsonb_build_object('requestId',req.id,'status','consumed','purpose',q.purpose,'targetId',q.target_id,'consumedAt',q.consumed_at,'staffConfirmationRequired',q.staff_required,'replayed',true);end if;if not found or not q.staff_required or q.state<>'active'or q.expires_at<=clock_timestamp()then raise exception'MOBILE_PARTICIPATION_QR_UNAVAILABLE';end if;if q.purpose='prize_pickup'then select*into award from public.mobile_benefit_awards where id=q.target_id and app_user_id=req.app_user_id and fulfillment_method='on_site_pickup'for update;if not found or award.fulfillment_status not in('ready','pickup_available')then raise exception'MOBILE_PARTICIPATION_PICKUP_UNAVAILABLE';end if;update public.mobile_benefit_awards set fulfillment_status='pickup_completed',updated_at=clock_timestamp()where id=award.id;elsif q.purpose='event_checkin'then insert into public.mobile_participation_checkins(event_id,app_user_id,source,policy_version,confirmed_by_admin_id)select e.id,req.app_user_id,'staff',e.policy_version,p_actor_admin_allowlist_id from public.mobile_participation_events e where e.id=q.target_id and e.state='published'and clock_timestamp()<e.ends_at on conflict(event_id,app_user_id)do update set status='valid',source='staff',policy_version=excluded.policy_version,confirmed_at=clock_timestamp(),confirmed_by_admin_id=excluded.confirmed_by_admin_id;if not found then raise exception'MOBILE_PARTICIPATION_EVENT_UNAVAILABLE';end if;elsif q.purpose<>'benefit_use'then raise exception'MOBILE_PARTICIPATION_QR_PURPOSE_INVALID';end if;update public.mobile_participation_qr_codes set state='consumed',consumed_at=clock_timestamp(),consumed_by_app_user_id=req.app_user_id where id=q.id returning*into q;insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'qr_confirmed',q.purpose,q.target_id,p_correlation_id,btrim(p_reason),jsonb_build_object('requestId',req.id,'appUserId',req.app_user_id));return jsonb_build_object('requestId',req.id,'status','consumed','purpose',q.purpose,'targetId',q.target_id,'consumedAt',q.consumed_at,'staffConfirmationRequired',q.staff_required,'replayed',false);end$$;

create function public.issue_admin_mobile_participation_qr(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_purpose text,p_target_type text,p_target_id uuid,p_owner_app_user_id uuid,p_policy_version text,p_expires_at timestamptz,p_one_time boolean,p_staff_required boolean,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare raw text:='byus_'||replace(extensions.gen_random_uuid()::text,'-','');q public.mobile_participation_qr_codes%rowtype;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if p_purpose not in('profile','stamp','live','event','space','album','event_checkin','benefit_use','prize_pickup')or p_expires_at<=clock_timestamp()or length(btrim(coalesce(p_reason,'')))not between 10 and 500 or p_correlation_id is null then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if p_purpose in('event_checkin','benefit_use','prize_pickup')and(not p_staff_required or not p_one_time)then raise exception'MOBILE_PARTICIPATION_QR_PURPOSE_INVALID';end if;insert into public.mobile_participation_qr_codes(token_hash,purpose,target_type,target_id,owner_app_user_id,policy_version,expires_at,one_time,staff_required,created_by_admin_id)values(encode(extensions.digest(raw,'sha256'),'hex'),p_purpose,p_target_type,p_target_id,p_owner_app_user_id,p_policy_version,p_expires_at,p_one_time,p_staff_required,p_actor_admin_allowlist_id)returning*into q;insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'qr_issued',p_purpose,p_target_id,p_correlation_id,btrim(p_reason),jsonb_build_object('qrId',q.id,'expiresAt',q.expires_at));return jsonb_build_object('id',q.id,'rawCode',raw,'purpose',q.purpose,'targetType',q.target_type,'targetId',q.target_id,'expiresAt',q.expires_at,'oneTime',q.one_time,'staffConfirmationRequired',q.staff_required);end$$;

create function public.upsert_admin_mobile_participation_event(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_event_id uuid,p_expected_revision integer,p_slug text,p_celebrity_id uuid,p_event_kind text,p_policy_version text,p_state text,p_starts_at timestamptz,p_ends_at timestamptz,p_title_ko text,p_title_en text,p_summary_ko text,p_summary_en text,p_application_url text,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare e public.mobile_participation_events%rowtype;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if length(btrim(coalesce(p_reason,'')))not between 10 and 500 then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if p_event_id is null then insert into public.mobile_participation_events(slug,celebrity_id,event_kind,policy_version,state,starts_at,ends_at,title_ko,title_en,summary_ko,summary_en,application_url)values(p_slug,p_celebrity_id,p_event_kind,p_policy_version,p_state,p_starts_at,p_ends_at,p_title_ko,p_title_en,coalesce(p_summary_ko,''),coalesce(p_summary_en,''),p_application_url)returning*into e;else update public.mobile_participation_events set slug=p_slug,celebrity_id=p_celebrity_id,event_kind=p_event_kind,policy_version=p_policy_version,state=p_state,starts_at=p_starts_at,ends_at=p_ends_at,title_ko=p_title_ko,title_en=p_title_en,summary_ko=coalesce(p_summary_ko,''),summary_en=coalesce(p_summary_en,''),application_url=p_application_url,revision=revision+1,updated_at=clock_timestamp()where id=p_event_id and revision=p_expected_revision returning*into e;if not found then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;end if;insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'event_upserted','event',e.id,p_correlation_id,btrim(p_reason),jsonb_build_object('revision',e.revision,'state',e.state));return jsonb_build_object('id',e.id,'revision',e.revision,'state',e.state,'policyVersion',e.policy_version);end$$;

create function public.upsert_admin_mobile_participation_context(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_context_id uuid,p_expected_revision integer,p_context_type text,p_source_live_event_id uuid,p_source_event_id uuid,p_celebrity_id uuid,p_slug text,p_policy_version text,p_state text,p_opens_at timestamptz,p_closes_at timestamptz,p_require_checkin boolean,p_album_kind text,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare c public.mobile_participation_contexts%rowtype;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if length(btrim(coalesce(p_reason,'')))not between 10 and 500 or(p_source_live_event_id is not null and not exists(select 1 from public.live_events where id=p_source_live_event_id and celebrity_id=p_celebrity_id))or(p_source_event_id is not null and not exists(select 1 from public.mobile_participation_events where id=p_source_event_id and celebrity_id=p_celebrity_id))then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if p_context_id is null then insert into public.mobile_participation_contexts(context_type,source_live_event_id,source_event_id,celebrity_id,slug,policy_version,state,opens_at,closes_at,require_checkin,album_kind)values(p_context_type,p_source_live_event_id,p_source_event_id,p_celebrity_id,p_slug,p_policy_version,p_state,p_opens_at,p_closes_at,p_require_checkin,p_album_kind)returning*into c;else update public.mobile_participation_contexts set context_type=p_context_type,source_live_event_id=p_source_live_event_id,source_event_id=p_source_event_id,celebrity_id=p_celebrity_id,slug=p_slug,policy_version=p_policy_version,state=p_state,opens_at=p_opens_at,closes_at=p_closes_at,require_checkin=p_require_checkin,album_kind=p_album_kind,revision=revision+1,updated_at=clock_timestamp()where id=p_context_id and revision=p_expected_revision returning*into c;if not found then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;end if;insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'context_upserted','context',c.id,p_correlation_id,btrim(p_reason),jsonb_build_object('revision',c.revision,'state',c.state,'type',c.context_type));return jsonb_build_object('id',c.id,'revision',c.revision,'state',c.state,'policyVersion',c.policy_version);end$$;

create function public.upsert_admin_mobile_participation_activity(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_activity_id uuid,p_expected_revision integer,p_context_id uuid,p_policy_version text,p_activity_kind text,p_state text,p_opens_at timestamptz,p_closes_at timestamptz,p_completion_seconds integer,p_max_heartbeat_gap_seconds integer,p_reward_config jsonb,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.mobile_participation_activity_policies%rowtype;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);if length(btrim(coalesce(p_reason,'')))not between 10 and 500 or not exists(select 1 from public.mobile_participation_contexts where id=p_context_id)then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if p_activity_id is null then insert into public.mobile_participation_activity_policies(context_id,policy_version,activity_kind,state,opens_at,closes_at,completion_seconds,max_heartbeat_gap_seconds,reward_config)values(p_context_id,p_policy_version,p_activity_kind,p_state,p_opens_at,p_closes_at,p_completion_seconds,p_max_heartbeat_gap_seconds,p_reward_config)returning*into a;else update public.mobile_participation_activity_policies set context_id=p_context_id,policy_version=p_policy_version,activity_kind=p_activity_kind,state=p_state,opens_at=p_opens_at,closes_at=p_closes_at,completion_seconds=p_completion_seconds,max_heartbeat_gap_seconds=p_max_heartbeat_gap_seconds,reward_config=p_reward_config,revision=revision+1 where id=p_activity_id and revision=p_expected_revision and not exists(select 1 from public.mobile_participation_activity_sessions where activity_id=p_activity_id)returning*into a;if not found then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;end if;insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'activity_upserted','activity',a.id,p_correlation_id,btrim(p_reason),jsonb_build_object('revision',a.revision,'state',a.state));return jsonb_build_object('id',a.id,'revision',a.revision,'state',a.state,'policyVersion',a.policy_version);end$$;

create function public.upsert_admin_mobile_participation_vote(p_actor_app_user_id uuid,p_actor_admin_allowlist_id uuid,p_vote_id uuid,p_expected_revision integer,p_context_id uuid,p_policy_version text,p_question text,p_state text,p_opens_at timestamptz,p_closes_at timestamptz,p_max_selections integer,p_change_allowed boolean,p_result_visibility text,p_options jsonb,p_reason text,p_correlation_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare v public.mobile_participation_votes%rowtype;option_count integer;begin perform public.assert_active_admin(p_actor_app_user_id,p_actor_admin_allowlist_id,true);option_count:=jsonb_array_length(coalesce(p_options,'[]'));if length(btrim(coalesce(p_reason,'')))not between 10 and 500 or option_count not between 2 and 100 or exists(select 1 from jsonb_array_elements(p_options)x where length(btrim(x->>'label'))not between 1 and 300)then raise exception'MOBILE_PARTICIPATION_INVALID';end if;if p_vote_id is null then insert into public.mobile_participation_votes(context_id,policy_version,question,state,opens_at,closes_at,max_selections,change_allowed,result_visibility)values(p_context_id,p_policy_version,p_question,p_state,p_opens_at,p_closes_at,p_max_selections,p_change_allowed,p_result_visibility)returning*into v;else update public.mobile_participation_votes set context_id=p_context_id,policy_version=p_policy_version,question=p_question,state=p_state,opens_at=p_opens_at,closes_at=p_closes_at,max_selections=p_max_selections,change_allowed=p_change_allowed,result_visibility=p_result_visibility,revision=revision+1 where id=p_vote_id and revision=p_expected_revision and not exists(select 1 from public.mobile_participation_vote_responses where vote_id=p_vote_id)returning*into v;if not found then raise exception'MOBILE_PARTICIPATION_CONFLICT';end if;delete from public.mobile_participation_vote_options where vote_id=v.id;end if;insert into public.mobile_participation_vote_options(vote_id,label,display_order)select v.id,btrim(x.value->>'label'),x.ordinality::integer from jsonb_array_elements(p_options)with ordinality x(value,ordinality);insert into public.mobile_participation_admin_audits(actor_app_user_id,actor_admin_allowlist_id,action,target_type,target_id,correlation_id,reason,detail)values(p_actor_app_user_id,p_actor_admin_allowlist_id,'vote_upserted','vote',v.id,p_correlation_id,btrim(p_reason),jsonb_build_object('revision',v.revision,'state',v.state,'optionCount',option_count));return jsonb_build_object('id',v.id,'revision',v.revision,'state',v.state,'policyVersion',v.policy_version);end$$;

