create function public.scrub_mobile_participation_on_account_disable()returns trigger language plpgsql security definer set search_path=''as $$begin if old.status='active'and new.status='disabled'then update public.mobile_participation_posts set status='deleted',revision=revision+1,updated_at=clock_timestamp()where app_user_id=new.id and status='valid';update public.mobile_participation_comments set status='deleted',revision=revision+1,updated_at=clock_timestamp()where app_user_id=new.id and status='valid';delete from public.mobile_participation_reactions where app_user_id=new.id;update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where app_user_id=new.id and attached_type='participation_post'and storage_deleted_at is null and state not in('cancelled','deleted');update public.mobile_participation_activity_sessions set state='deleted',version=version+1,updated_at=clock_timestamp()where app_user_id=new.id and state in('viewing','completing','completed');update public.mobile_participation_activity_rewards r set status=case when r.status='awarded'then'revoked'else'cancelled'end,updated_at=clock_timestamp()where r.session_id in(select id from public.mobile_participation_activity_sessions where app_user_id=new.id);update public.mobile_participation_qr_codes set state='revoked'where owner_app_user_id=new.id and state='active';end if;return new;end$$;
